function volumeY(gain){return clamp((2-gain)*30,4,56);}
function volumeSegmentPath(c,index){const nodes=volumeNodes(c),a=nodes[index],b=nodes[index+1];if(!a||!b)return '';let path='M'+a.time+' '+volumeY(a.gain);if(!a.bend&&Math.abs(a.curve||0)<1e-8)return path+' L'+b.time+' '+volumeY(b.gain);for(let i=1;i<=96;i++){const time=a.time+(b.time-a.time)*i/96;path+=' L'+time+' '+volumeY(volumeEnvelope(c,time,nodes));}return path;}
