function curveHandlePosition(c,index){const nodes=volumeNodes(c),a=nodes[index],b=nodes[index+1],fraction=a.bend?.x??.5,time=a.time+(b.time-a.time)*fraction,gain=a.bend?.gain??volumeEnvelope(c,time,nodes);return {time,gain,fraction,x:time/c.duration*100,y:volumeY(gain)/60*100,curve:a.curve||0};}
function curveHandleLabel(){return 'Control de curva · arrastra en cualquier dirección · flechas para ajustar · doble clic para volver a recta';}
function volumeLabel(gain){return volumeUnit==='percent'?Math.round(gain*100)+' %':gain?(20*Math.log10(gain)).toFixed(1)+' dB':'silencio';}
function volumeValue(gain){return volumeUnit==='percent'?Number((gain*100).toFixed(1)):gain?Number((20*Math.log10(gain)).toFixed(1)):'';}
function volumePointFor(c){return selectedVolumePoint?.clipId===c.id?(c.volumePoints||[]).find(p=>Math.abs(p.time-selectedVolumePoint.time)<.003):null;}
function volumeEditor(c){const point=volumePointFor(c),gain=point?.gain??volumeNodes(c)[0].gain;return `<div class="section-label">LÍNEA DE VOLUMEN</div><div class="volume-value-editor"><label>Nivel<input id="volumeValue" type="number" min="${volumeUnit==='percent'?0:''}" placeholder="${volumeUnit==='db'&&gain===0?'−∞':'0'}" step="${volumeUnit==='percent'?1:.1}" value="${volumeValue(gain)}" aria-label="Nivel de la línea de volumen"></label><label>Unidad<select id="volumeUnit" aria-label="Unidad de volumen"><option value="db" ${volumeUnit==='db'?'selected':''}>dB</option><option value="percent" ${volumeUnit==='percent'?'selected':''}>%</option></select></label></div><p class="volume-value-note" id="volumeValueTarget">${point?'Punto · '+formatTime(c.start+point.time,true):'Bloque completo · nivel de toda la línea'}</p>`;}
function syncVolumeValue(c){const input=$('#volumeValue');if(input&&findClip(project,selectedClip)?.clip.id===c.id){const point=volumePointFor(c);input.value=volumeValue(point?.gain??volumeNodes(c)[0].gain);$('#volumeValueTarget').textContent=point?'Punto · '+formatTime(c.start+point.time,true):'Bloque completo · nivel de toda la línea';}}
