function updateVolumeGraphics(el,c){const container=el.querySelector('.volume-envelope');container.querySelector('.volume-line').setAttribute('d',volumePath(c));for(const path of container.querySelectorAll('.volume-line-hit'))path.setAttribute('d',volumeSegmentPath(c,Number(path.dataset.curveIndex)));const points=volumeNodes(c);container.querySelectorAll('.volume-point').forEach((button,i)=>{const point=points[i];if(!point)return;button.style.left=(point.time/c.duration*100)+'%';button.style.top=(clamp((2-point.gain)*30,4,56)/60*100)+'%';button.dataset.volumeTime=point.time;button.dataset.volumeGain=point.gain;button.setAttribute('aria-label','Volumen '+volumeLabel(point.gain)+' · '+formatTime(c.start+point.time,true));button.title='Punto de volumen · '+volumeLabel(point.gain)+' · arrastra arriba o abajo';});for(const button of container.querySelectorAll('.volume-curve-handle')){const h=curveHandlePosition(c,Number(button.dataset.curveIndex));button.style.left=h.x+'%';button.style.top=h.y+'%';button.title=curveHandleLabel(h.curve);button.setAttribute('aria-label',button.title);}drawWave(el);engine.updateClip(c);syncVolumeValue(c);}
function clipHTML(c,t){const fd=sources.get(c.source);return `<div class="clip ${selectedClips.has(c.id)?'selected':''}" data-clip="${c.id}" data-track="${t.id}" tabindex="0" role="button" aria-label="${esc(c.name)}, inicio ${formatTime(c.start,true)}, duración ${formatTime(c.duration,true)}" style="left:${c.start*zoom}px;width:${Math.max(4,c.duration*zoom)}px;--color:${trackVisual(t).color}" title="${esc(c.name)} · arrastra para mover; extremos para recortar"><div class="clip-label"><button class="clip-play" type="button" aria-label="Escuchar únicamente ${esc(c.name)}" aria-pressed="false" title="Escuchar este bloque de audio" ${editingBusy()?'disabled':''}>${icon('play')}</button><span>${esc(c.name)}</span></div><canvas></canvas><svg class="fade-line" viewBox="0 0 100 62" preserveAspectRatio="none"><path d="M0 ${c.fadeIn?60:1} L${c.duration?c.fadeIn/c.duration*100:0} 1 L${c.duration?(c.duration-c.fadeOut)/c.duration*100:100} 1 L100 ${c.fadeOut?60:1}"/></svg>${volumeHTML(c)}${(c.points||[]).map(point=>`<button class="edit-point" data-point="${point}" style="left:${point/c.duration*100}%" aria-label="Punto de edición ${formatTime(c.start+point,true)}" title="Marcador de corte · clic derecho para seleccionar un tramo"></button>`).join('')}<div class="clip-range" style="display:${project.region?.clipId===c.id?'block':'none'};left:${project.region?.clipId===c.id?(project.region.start-c.start)/c.duration*100:0}%;width:${project.region?.clipId===c.id?(project.region.end-project.region.start)/c.duration*100:0}%"></div><div class="clip-handle left" data-handle="left" title="Recortar inicio"></div><div class="clip-handle right" data-handle="right" title="Recortar final"></div></div>`;}
function peakCache(buffer){if(waveCache.has(buffer))return waveCache.get(buffer);const channels=Array.from({length:buffer.numberOfChannels},(_,i)=>buffer.getChannelData(i)),stride=128,peaks=new Float32Array(Math.ceil(buffer.length/stride)*2);for(let p=0,i=0;i<buffer.length;i+=stride,p+=2){let lo=0,hi=0;for(let j=i;j<Math.min(i+stride,buffer.length);j++)for(const data of channels){lo=Math.min(lo,data[j]);hi=Math.max(hi,data[j]);}peaks[p]=lo;peaks[p+1]=hi;}const cache={peaks,stride};waveCache.set(buffer,cache);return cache;}
function drawWave(el){const found=findClip(project,el.dataset.clip);if(!found)return;const {clip,track}=found,buffer=sources.get(clip.source);if(!buffer)return;const canvas=el.querySelector('canvas'),width=Math.min(6000,Math.max(4,Math.ceil(clip.duration*zoom))),height=Math.max(8,canvas.clientHeight||60);canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');if(!ctx)return;const {peaks,stride}=peakCache(buffer);ctx.strokeStyle=trackVisual(track).wave;ctx.globalAlpha=.9;ctx.lineWidth=1;ctx.beginPath();const gain=Math.min(2,dbGain(clip.gain)),volumePoints=volumeNodes(clip);for(let x=0;x<width;x+=2){const from=Math.floor((clip.offset+clip.duration*x/width)*buffer.sampleRate/stride),to=Math.min(peaks.length/2,Math.ceil((clip.offset+clip.duration*(x+2)/width)*buffer.sampleRate/stride));let lo=0,hi=0;for(let i=from;i<to;i++){lo=Math.min(lo,peaks[i*2]);hi=Math.max(hi,peaks[i*2+1]);}const level=envelope(clip,clip.duration*x/width,volumePoints)*gain;ctx.moveTo(x,height/2+lo*height*.45*level);ctx.lineTo(x,height/2+hi*height*.45*level);}ctx.stroke();ctx.globalAlpha=.25;ctx.beginPath();ctx.moveTo(0,height/2);ctx.lineTo(width,height/2);ctx.stroke();}
