function updatePlayhead(){const x=trackWidth()+position*zoom;$('#playhead').style.left=x+'px';$('#timeDisplay').textContent=formatTime(position,true);if(recording){const el=$('#recordingClip');if(el){el.style.left=(recording.start*zoom)+'px';el.style.width=Math.max(5,(position-recording.start)*zoom)+'px';}}}
