function mixerEQ(track){return `<fieldset class="channel-eq"><legend>ECUALIZADOR</legend>${[['low','Graves','200 Hz'],['mid','Medios','1,5 kHz'],['high','Agudos','5,5 kHz']].map(([band,label,freq])=>`<label><span>${label} <small>${freq}</small><output data-eq-value="${band}">${track.eq[band].toFixed(1)} dB</output></span><input data-eq="${band}" type="range" min="-12" max="12" step="0.5" value="${track.eq[band]}" aria-label="${label} de ${esc(track.name)}"></label>`).join('')}<label class="channel-comp"><input data-compressor type="checkbox" ${track.compressor?'checked':''}>Compresor de voz</label><button data-action="reset-eq" type="button" title="Restablecer las tres bandas y desactivar el compresor">Restablecer EQ</button></fieldset>`;}
