function fitZoom(){const available=$('#arrangeScroll').clientWidth-trackWidth()-35;zoom=clamp(available/Math.max(10,projectDuration(project)+3),5,200);$('#zoomRange').value=zoom;$('#arrangeScroll').scrollLeft=0;renderTimeline();updatePlayhead();}
function setZoom(value){zoom=clamp(value,5,200);$('#zoomRange').value=zoom;renderTimeline();updatePlayhead();}
function zoomTimelineWithWheel(e){
  if(!welcomeDismissed||startingSession||recordPending||importing||exporting||dragging||curveDragging||draggedTrack||e.buttons||$('dialog[open]'))return;
  if(e.ctrlKey||e.metaKey||e.altKey||(!e.deltaY&&!e.deltaX))return;
  if(e.target.closest('.track-controls,.ruler-spacer,.track-height-handle,input,textarea,select,[contenteditable="true"]'))return;
  const scroll=$('#arrangeScroll'),rect=scroll.getBoundingClientRect();
  const x=e.clientX-rect.left-scroll.clientLeft,controls=trackWidth();
  if(x<controls||x>scroll.clientWidth)return;
  if(e.shiftKey||Math.abs(e.deltaX)>Math.abs(e.deltaY)){
    const delta=(e.deltaX||e.deltaY)*(e.deltaMode===1?16:e.deltaMode===2?scroll.clientWidth-controls:1);
    e.preventDefault();scroll.scrollLeft=clamp(scroll.scrollLeft+delta,0,Math.max(0,scroll.scrollWidth-scroll.clientWidth));syncTimelineScroll();return;
  }
  const time=Math.max(0,(scroll.scrollLeft+x-controls)/zoom),top=scroll.scrollTop;
  const delta=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?scroll.clientHeight:1);
  const value=clamp(zoom*Math.exp(-clamp(delta,-160,160)*.002),5,200);
  e.preventDefault();
  if(Math.abs(value-zoom)<.000001)return;
  hideContextMenu();setZoom(value);
  scroll.scrollLeft=clamp(controls+time*zoom-x,0,Math.max(0,scroll.scrollWidth-scroll.clientWidth));
  scroll.scrollTop=top;syncTimelineScroll();
}
