  micTesting=false;micMonitorTrack=null;recorder?.cleanup();
  $('#testMic').textContent='Probar micro';$('#testMic').classList.remove('active');$('#testMic').setAttribute('aria-pressed','false');
  if(disarm&&target){const track=project.tracks.find(t=>t.id===target);if(track?.armed){track.armed=false;dirty();render();}}
  if(!quiet)setMicStatus(heard?'Entrada detenida · señal recibida':'Entrada detenida · no se recibió señal',!heard);
  updateMicrophoneMeter();setRecordUI();
